// The OpenAPI description of /-/api (feature: OpenAPI document). apiDocs
// describes every pattern apiRoutes and Routes register (and the server
// package's /-/metrics); internal/openapi's coverage test checks the list
// against the registrations in the source.

func (u *UI) openAPI(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.Write(openapi.Document())
}

func init() { openapi.Register(apiDocs...) }

